sp_CriarProduto	ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION	CREATE DEFINER=`root`@`%` PROCEDURE `sp_CriarProduto`(\n\n    p_idEmpresa          INT,\n\n    p_Nome               VARCHAR(60),\n\n    p_Descricao          VARCHAR(120),\n\n    p_codBarras          VARCHAR(14),\n\n    p_categoriaProduto_id INT,\n\n    p_precoCusto         DECIMAL(10,2),\n\n    p_precoVenda         DECIMAL(10,2),\n\n    p_fAtivo             TINYINT(1)\n\n)\nBEGIN\n\n    INSERT INTO Produto (\n\n        Nome, Descricao, codBarras,\n\n        categoriaProduto_id, precoCusto, precoVenda,\n\n        dthCadastro, idEmpresa, fAtivo\n\n    ) VALUES (\n\n        p_Nome, p_Descricao, p_codBarras,\n\n        p_categoriaProduto_id, p_precoCusto, p_precoVenda,\n\n        CURDATE(), p_idEmpresa, p_fAtivo\n\n    );\n\n\n\n    SET @novo_id = LAST_INSERT_ID();\n\n\n\n    \n\n    INSERT INTO Estoque (\n\n        produto_id, QtdeAtual, estoqueMin,\n\n        estoqueMax, dthAtualizacao, idEmpresa\n\n    ) VALUES (\n\n        @novo_id, 0, 0, 0, CURDATE(), p_idEmpresa\n\n    );\n\n\n\n    SELECT @novo_id AS idProduto;\n\nEND	utf8mb4	utf8mb4_0900_ai_ci	utf8mb4_0900_ai_ci
